#!/usr/bin/env bash
# D5a-3b READ-ONLY schema look 2 (22 Nov 2026 23:4x PKT): his first paste showed orgs 7 rows, polar_subscriptions 0 rows, mailbox_storage 5 rows. The per-company plan lives in public.workspace_subscriptions (sql/phase21). This lists its real columns and COUNTS only (no row data, no email, no secret) and checks how the tables link.
set -uo pipefail
. /etc/anexomail/sync.env 2>/dev/null; [ -n "${WORKING_URL:-}" ] || { echo "FAIL: WORKING_URL missing in /etc/anexomail/sync.env"; exit 2; }
env -u PGHOST -u PGPORT -u PGUSER -u PGDATABASE -u PGSERVICE psql "$WORKING_URL" -X -q -P pager=off -c "set default_transaction_read_only = on" \
 -c "select table_name, string_agg(column_name||':'||data_type, ', ' order by ordinal_position) as columns from information_schema.columns where table_schema='public' and table_name in ('workspace_subscriptions','workspace_plans') group by table_name order by 1" \
 -c "select 'workspace_subscriptions' t, count(*) n from public.workspace_subscriptions union all select 'subs with org_id', count(*) from public.workspace_subscriptions where org_id is not null union all select 'subs by state '||coalesce(state,'null'), count(*) from public.workspace_subscriptions group by state union all select 'subs by plan '||coalesce(plan,'null'), count(*) from public.workspace_subscriptions group by plan union all select 'mailbox_storage workspace_id = orgs.id', count(*) from public.mailbox_storage m join public.orgs o on o.id = m.workspace_id union all select 'mailbox_storage workspace_id = subs.org_id', count(*) from public.mailbox_storage m join public.workspace_subscriptions s on s.org_id = m.workspace_id union all select 'orgs with a subscription', count(*) from public.orgs o join public.workspace_subscriptions s on s.org_id = o.id union all select 'org_members', count(*) from public.org_members" 2>&1 | cut -c1-700
